import { cx } from '@/lib/cx';
import './divider.css';

/**
 * B29 · Divider — a hairline that separates two groups, optionally
 * naming the group below it in mono uppercase. A labelled divider is a
 * section marker, not a heading: it never replaces an <h2>.
 */
export interface DividerProps {
  /** Mono uppercase text sitting in the rule, e.g. "OR" or "ARCHIVED". */
  label?: string;
  align?: 'start' | 'center';
  className?: string;
}

export function Divider({ label, align = 'center', className }: DividerProps) {
  if (!label) return <hr className={cx('sv-divider', className)} />;
  return (
    <div
      className={cx('sv-divider__labelled', align === 'start' && 'sv-divider__labelled--start', className)}
      role="separator"
      aria-label={label}
    >
      <span className="sv-divider__rule" aria-hidden="true" />
      <span className="sv-divider__label sv-mono" aria-hidden="true">
        {label}
      </span>
      <span className="sv-divider__rule" aria-hidden="true" />
    </div>
  );
}

/* B29 · Divider — one hairline, optionally carrying a mono label. */

@layer sv-components {
  .sv-divider {
    height: 1px;
    border: 0;
    background: var(--sv-line);
  }

  .sv-divider__labelled {
    display: flex;
    align-items: center;
    gap: var(--sv-s3);
  }

  .sv-divider__rule {
    flex: 1;
    height: 1px;
    background: var(--sv-line);
  }

  /* start alignment keeps the label flush left; the rule runs on past it. */
  .sv-divider__labelled--start .sv-divider__rule:first-child {
    display: none;
  }

  .sv-divider__label {
    font-size: 9.5px;
    letter-spacing: 0.13em;
    text-transform: uppercase;
    color: var(--sv-ink-soft);
    white-space: nowrap;
  }

  .sv-band .sv-divider,
  .sv-band .sv-divider__rule {
    background: var(--sv-band-line);
  }

  .sv-band .sv-divider__label {
    color: var(--sv-band-soft);
  }
}
